// QUICClientHello captures the TLS ClientHello information extracted from
// QUIC Initial packets. For IETF QUIC, this is an embedded TLS 1.3 ClientHello.
// For gQUIC, this is the CHLO (Client Hello) message with proprietary tags.
// This enables JA4 fingerprinting with the 'q' protocol prefix.
type QUICClientHello struct {
	Timestamp int64  `protobuf:"varint,1,opt,name=Timestamp,proto3" json:"Timestamp,omitempty"`
	SrcIP     string `protobuf:"bytes,2,opt,name=SrcIP,proto3" json:"SrcIP,omitempty"`
	DstIP     string `protobuf:"bytes,3,opt,name=DstIP,proto3" json:"DstIP,omitempty"`
	SrcPort   int32  `protobuf:"varint,4,opt,name=SrcPort,proto3" json:"SrcPort,omitempty"`
	DstPort   int32  `protobuf:"varint,5,opt,name=DstPort,proto3" json:"DstPort,omitempty"`
	// QUIC-specific
	QUICVersion string `protobuf:"bytes,6,opt,name=QUICVersion,proto3" json:"QUICVersion,omitempty"`
	IsIETFQUIC  bool   `protobuf:"varint,7,opt,name=IsIETFQUIC,proto3" json:"IsIETFQUIC,omitempty"`
	DCID        []byte `protobuf:"bytes,8,opt,name=DCID,proto3" json:"DCID,omitempty"`
	SCID        []byte `protobuf:"bytes,9,opt,name=SCID,proto3" json:"SCID,omitempty"`
	// TLS ClientHello fields (IETF QUIC embeds TLS 1.3)
	SNI              string   `protobuf:"bytes,10,opt,name=SNI,proto3" json:"SNI,omitempty"`
	ALPNs            []string `protobuf:"bytes,11,rep,name=ALPNs,proto3" json:"ALPNs,omitempty"`
	CipherSuites     []int32  `protobuf:"varint,12,rep,packed,name=CipherSuites,proto3" json:"CipherSuites,omitempty"`
	Extensions       []int32  `protobuf:"varint,13,rep,packed,name=Extensions,proto3" json:"Extensions,omitempty"`
	SupportedGroups  []int32  `protobuf:"varint,14,rep,packed,name=SupportedGroups,proto3" json:"SupportedGroups,omitempty"`
	SignatureAlgs    []int32  `protobuf:"varint,15,rep,packed,name=SignatureAlgs,proto3" json:"SignatureAlgs,omitempty"`
	SupportedVersion int32    `protobuf:"varint,16,opt,name=SupportedVersion,proto3" json:"SupportedVersion,omitempty"`
	// gQUIC-specific CHLO tags (from Google QUIC CHLO message)
	UAID      string            `protobuf:"bytes,17,opt,name=UAID,proto3" json:"UAID,omitempty"`
	CHLOTags  []string          `protobuf:"bytes,18,rep,name=CHLOTags,proto3" json:"CHLOTags,omitempty"`
	TagValues map[string]string `protobuf:"bytes,19,rep,name=TagValues,proto3" json:"TagValues,omitempty" protobuf_key:"bytes,1,opt,name=key,proto3" protobuf_val:"bytes,2,opt,name=value,proto3"`
	// Fingerprints
	Ja4            string `protobuf:"bytes,20,opt,name=Ja4,proto3" json:"Ja4,omitempty"`
	Ja4Description string `protobuf:"bytes,30,opt,name=Ja4Description,proto3" json:"Ja4Description,omitempty"`
	// QUIC Transport Parameters (IETF QUIC - from TLS extension 0x39)
	MaxIdleTimeout                int64 `protobuf:"varint,22,opt,name=MaxIdleTimeout,proto3" json:"MaxIdleTimeout,omitempty"`
	InitialMaxData                int64 `protobuf:"varint,23,opt,name=InitialMaxData,proto3" json:"InitialMaxData,omitempty"`
	InitialMaxStreamDataBidiLocal int64 `protobuf:"varint,24,opt,name=InitialMaxStreamDataBidiLocal,proto3" json:"InitialMaxStreamDataBidiLocal,omitempty"`
	MaxUdpPayloadSize             int64 `protobuf:"varint,25,opt,name=MaxUdpPayloadSize,proto3" json:"MaxUdpPayloadSize,omitempty"`
	// Additional TLS fields for completeness
	Random          []byte  `protobuf:"bytes,26,opt,name=Random,proto3" json:"Random,omitempty"`
	SessionID       []byte  `protobuf:"bytes,27,opt,name=SessionID,proto3" json:"SessionID,omitempty"`
	SupportedPoints []int32 `protobuf:"varint,28,rep,packed,name=SupportedPoints,proto3" json:"SupportedPoints,omitempty"`
	CompressMethods []int32 `protobuf:"varint,29,rep,packed,name=CompressMethods,proto3" json:"CompressMethods,omitempty"`
	// Community ID v1 for cross-tool correlation (Zeek, Suricata, etc.)
	CommunityID string `protobuf:"bytes,31,opt,name=CommunityID,proto3" json:"CommunityID,omitempty"`
}

